7	+using Microsoft.EntityFrameworkCore;
8	+using seed_b_backend.Api.Data;
9	+using seed_b_backend.Api.Domain;
10	+
11	+namespace seed_b_backend.Api.Application;
12	+
13	+public class RatingService(AppDbContext db)
14	+{
15	+    public async Task<bool> SubmitRatingAsync(string productId, string authorName, int value, CancellationToken cancellationToken = default)
16	+    {
17	+        if (!await db.Products.AnyAsync(p => p.Id == productId, cancellationToken))
18	+        {
19	+            return false;
20	+        }
21	+
22	+        await UpsertRatingAsync(productId, authorName, value, isRetry: false, cancellationToken);
23	+        return true;
24	+    }
25	+
26	+    private async Task UpsertRatingAsync(string productId, string authorName, int value, bool isRetry, CancellationToken cancellationToken)
27	+    {
28	+        await using var transaction = await db.Database.BeginTransactionAsync(cancellationToken);
29	+
30	+        await db.Ratings
31	+            .Where(r => r.ProductId == productId && r.AuthorName == authorName)
32	+            .ExecuteDeleteAsync(cancellationToken);
33	+
34	+        db.Ratings.Add(new Rating { ProductId = productId, AuthorName = authorName, Value = value });
35	+
36	+        try
37	+        {
38	+            await db.SaveChangesAsync(cancellationToken);
39	+            await transaction.CommitAsync(cancellationToken);
40	+        }
41	+        catch (DbUpdateException) when (!isRetry)
42	+        {
43	+            await transaction.RollbackAsync(cancellationToken);
44	+            db.ChangeTracker.Clear();
45	+            await UpsertRatingAsync(productId, authorName, value, isRetry: true, cancellationToken);
46	+        }
47	+    }
48	+}
