7	public class RatingService(AppDbContext db)
8	{
9	    public async Task<bool> SubmitRatingAsync(string productId, string authorName, int value, CancellationToken cancellationToken = default)
10	    {
11	        if (!await db.Products.AnyAsync(p => p.Id == productId, cancellationToken))
12	        {
13	            return false;
14	        }
15	
16	        await UpsertRatingAsync(productId, authorName, value, isRetry: false, cancellationToken);
17	        return true;
18	    }
19	
20	    private async Task UpsertRatingAsync(string productId, string authorName, int value, bool isRetry, CancellationToken cancellationToken)
21	    {
22	        await using var transaction = await db.Database.BeginTransactionAsync(cancellationToken);
23	
24	        await db.Ratings
25	            .Where(r => r.ProductId == productId && r.AuthorName == authorName)
26	            .ExecuteDeleteAsync(cancellationToken);
27	
28	        db.Ratings.Add(new Rating { ProductId = productId, AuthorName = authorName, Value = value });
29	
30	        try
31	        {
32	            await db.SaveChangesAsync(cancellationToken);
33	            await transaction.CommitAsync(cancellationToken);
34	        }
35	        catch (DbUpdateException) when (!isRetry)
36	        {
37	            await transaction.RollbackAsync(cancellationToken);
38	            db.ChangeTracker.Clear();
39	            await UpsertRatingAsync(productId, authorName, value, isRetry: true, cancellationToken);
40	        }
41	    }
42	}
